const ATTEMPT_TIMEOUT_MS = 5000;

function readPackageJsonContent(): Promise<{ name?: string; version?: string }> {
  let resolvedUrl = __filename;
  while (!resolvedUrl.includes('/dist/') && !resolvedUrl.includes('/node_modules/')) {
    resolvedUrl = resolvedUrl.replace(/\\\/[^\\\/]+$/, '/');
  }
  const packagePath = resolvedUrl.replace(/\\/+\$/, '/package.json');
  const dir = packagePath.replace(/\\/+\$/, '');
  if (dir.endsWith('/package.json')) {
    try {
      const { name, version } = JSON.parse(await import('/package.json')) as { name?: string; version?: string };
      return { name, version };
    } catch {
      const { name, version } = await import('file:' + packagePath) as { name?: string; version?: string };
      return { name, version };
    }
  }
  throw new Error('Could not locate package.json');
}

